#!/usr/bin/env python3
"""Build static, no-login-needed executive pages from measured immutable evidence."""
from __future__ import annotations

import csv
import html
import hashlib
import io
import json
import shutil
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / "docs"


def esc(value):
    return html.escape(str(value), quote=True)


def load(name):
    return json.loads((ROOT / name).read_text())


def pct(value):
    return f"{100 * value:.2f}%"


def number(value):
    return f"{value:,.0f}"


def holdout_text(record):
    lo, hi = record["ci95"]["interval"]
    return f"{record['dti']:.4f} · 95% CI {lo:.4f}–{hi:.4f}"


def shell(title, body, active="Executive summary", *, prefix=""):
    # Keyboard users must be able to scroll evidence tables on small screens.
    for index in range(body.count('<div class="table-wrap">')):
        body = body.replace('<div class="table-wrap">',
                            f'<div class="table-wrap" tabindex="0" role="region" aria-label="{esc(title)} evidence table {index + 1}">', 1)
    nav = [("Executive summary", "executive-summary.html", "01"), ("Nine-site review", "sites.html", "02"),
           ("Submission guide", "submission-guide.html", "03"), ("Science & method", "research.html", "04"),
           ("Sources & limits", "sources.html", "05")]
    items = "".join(f'<a class="nav-link {"active" if label == active else ""}" href="{prefix}{url}"><span>{index}</span>{label}</a>' for label, url, index in nav)
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{esc(title)} · ApartGEMS</title><meta name="description" content="Evidence-first GEMS fault mapping, automated GeoTIFF checks, and transparent submission readiness.">
<link rel="stylesheet" href="{prefix}assets/style.css"><script src="{prefix}assets/app.js" defer></script></head>
<body><a class="skip-link" href="#main">Skip to content</a><aside class="sidebar"><a class="brand" href="{prefix}index.html"><span class="brand-mark">A<span>↗</span></span><span>ApartGEMS<small>FAULT DISCOVERY LAB</small></span></a>
<div class="nav-caption">RESEARCH WORKSPACE</div><nav aria-label="Main">{items}</nav><div class="sidebar-bottom"><span class="status-dot"></span> Evidence, not projections<p>One research lane.<br>No submission slots spent.</p><a href="https://github.com/apartanish22-droid/ApartGEMSDOE1">View repository ↗</a></div></aside>
<div class="page"><header class="topbar"><span class="breadcrumb">GEMS Prize <span>/</span> {esc(title)}</span><span class="snapshot"><span class="status-dot"></span> Snapshot · 27 Oct 2026 UTC</span></header>
<main id="main">{body}</main><footer><span>ApartGEMS · Reproducible fault-mapping research</span><span>Historical reports ≠ organizer receipts · Holdout ≠ leaderboard</span></footer></div></body></html>'''


def site_card(row, *, prefix=""):
    return f'''<a class="site-card" href="{prefix}sites/{row['site']}.html"><div><span class="eyebrow">HISTORICAL REFERENCE</span><h3>{row['site']}</h3></div><span class="historical-value">No receipt<small>historical reference only</small></span><div class="site-card-bottom"><span>{number(row['positive_pixels'])} positive pixels inspected</span><span>Review →</span></div></a>'''


def historical_table_rows(focus):
    """Historical artifacts are reference-only, never estimated or approved scores."""
    return "".join(f'''<tr><td><a class="table-site" href="sites/{row['site']}.html">{row['site']} ↗</a>{'<small class="table-hint">Highest historical claim</small>' if row['site']=='GEMSDOE32' else ''}</td><td><strong>Unavailable</strong><small class="table-hint">No exact-file organizer receipt</small></td><td><code class="filename">{esc(row['inspected_filename'])}</code></td><td><span class="pill fail">NO</span><small class="table-hint">{pct(row['max_3px_overlap_vs_other_focus_champions'])} max near-dot overlap</small></td><td>Not estimable<small class="table-hint">No exact-file receipt or calibrated forecast</small></td><td><strong>None approved</strong><small class="table-hint">Do not resubmit historical file</small></td></tr>''' for row in focus["rows"])


def validate_build_inputs(experiment, card):
    """This builder is authorized for the frozen negative release only."""
    if any(record.get("verdict") != "negative" or record.get("ok_to_submit") is not False for record in (experiment, card)):
        raise ValueError("Not an authorized negative research release; a selector cannot be invented by the site builder")
    if experiment["readiness"].get("ok_to_submit") is not False:
        raise ValueError("Research builder cannot publish a selector-approved release")
    if card["raster_sha256"] != experiment["artifact"]["sha256"] or card["holdout"] != experiment["holdout"]:
        raise ValueError("Run card and experiment artifact/measurement disagree")
    if not 0 < len(experiment["submission_note"]) <= 140 or card["submission_note"] != experiment["submission_note"]:
        raise ValueError("Invalid or mismatched short submission note")


def main():
    experiment = load("evidence/experiment.json")
    if not experiment.get("finished_utc") or "artifact" not in experiment:
        raise SystemExit("No completed, auditable artifact. Do not build an apparent download approval from a partial run.")
    focus = load("evidence/focus-audit.json")
    registry = load("evidence/registry.json")
    sources = load("research/sources.json")
    card = load("evidence/run-card.json")
    holdout = experiment["holdout"]
    base = experiment["baseline_holdout"]
    paired = experiment["paired_comparison"]
    artifact = experiment["artifact"]
    final_registry = load("evidence/final-registry.json")
    ordered = sorted(final_registry["rows"], key=lambda r: r["candidate_dot_overlap_within_3px"], reverse=True)
    non_lattice = [row for row in ordered if "r13-lattice" not in row["file"]]
    filename = artifact["filename"]
    download = "downloads/" + filename
    note = experiment["submission_note"]
    validate_build_inputs(experiment, card)
    current_file = ROOT / artifact["path"]
    if not current_file.is_file() or hashlib.sha256(current_file.read_bytes()).hexdigest() != artifact["sha256"]:
        raise ValueError("Missing or changed research download; refusing to publish an apparent valid artifact")
    for folder in ("data", "sites", "assets", "research"):
        (DOCS / folder).mkdir(exist_ok=True)
    for source, destination in [("evidence/experiment.json", "data/experiment.json"), ("evidence/run-card.json", "data/run-card.json"),
                                ("evidence/focus-audit.json", "data/focus-audit.json"), ("evidence/source-pins.json", "data/source-pins.json"),
                                ("research/sources.json", "data/sources.json"), ("evidence/final-registry.json", "data/final-registry.json"),
                                ("evidence/surface-registry.json", "data/surface-registry.json"),
                                ("research/hypotheses-2026-10-27.md", "research/hypotheses-2026-10-27.md"),
                                ("research/claims.csv", "data/claims.csv"), ("research/data-catalog.csv", "data/data-catalog.csv")]:
        shutil.copyfile(ROOT / source, DOCS / destination)
    for alias in (ROOT / "run_card.json", DOCS / "run_card.json"):
        shutil.copyfile(ROOT / "evidence/run-card.json", alias)
    for report_name in ("source-health.json", "release-verification.json", "browser-verification.json", "restoration-verification.json", "review-ledger.json"):
        source = ROOT / "evidence" / report_name
        if source.exists():
            shutil.copyfile(source, DOCS / "data" / report_name)
    ready = experiment["readiness"]["ok_to_submit"]
    if ready:
        raise ValueError("This static release is quarantined; a new selector-authorized release requires an explicit new build contract")
    gate_labels = {
        "format_and_range": "GeoTIFF format, numeric range & footprint mask",
        "byte_and_prediction_unique": "New bytes & distinct prediction array in audited registry",
        "feature_canaries": "All source/descriptor leakage canaries",
        "surface_novelty": "Surface uniqueness before dot placement",
        "final_dot_novelty": "Final-dot uniqueness against every registry raster",
        "complete_registry": "Complete cross-project uniqueness coverage",
        "paired_local_improvement": "Paired improvement over matched-budget ablation",
        "beats_comparable_current_best": "Beats a verified comparable current holdout best",
        "assigned_lane": "Explicit parallel-run lane assignment",
        "authenticated_data_provenance": "Organizer-authenticated input provenance",
        "separate_selector_approved": "Separate selector approval",
        "weekly_quota_verified": "Remaining weekly entity quota verified",
    }
    gate_rows = "".join(f'<tr><td>{esc(gate_labels[key])}</td><td><span class="pill {"pass" if passed else "fail"}">{"PASS" if passed else "NOT PASSED"}</span></td></tr>' for key, passed in experiment["readiness"]["gates"].items())
    rows = historical_table_rows(focus)
    overview = f'''
<div class="page-heading"><div><span class="eyebrow">EXECUTIVE SUMMARY / AP1-SNRC</span><h1>Submission readiness.</h1><p class="lead">A new prediction file, tested end to end. No hidden approvals.</p></div><a class="quiet-link" href="data/run-card.json" download>Download run card ↓</a></div>
<section class="decision-grid" aria-label="Submission decision"><div class="decision-panel"><span class="pill fail">DO NOT SUBMIT</span><h2>Locally valid. <br>Negative research result.</h2><p>Distinct bytes and predictions, but <strong>final-dot uniqueness failed</strong> and the holdout ablation won. Mandatory STOP after one experiment. No further tuning or competition upload.</p><div class="decision-meta"><span>Automated validation</span><strong>No human-inspection dependency</strong></div></div>
<div class="download-panel"><div class="file-icon">TIF</div><span class="eyebrow">NEWLY GENERATED · RESEARCH ONLY</span><h2>AP1-SNRC · experiment 1</h2><p>Scarp-normal radiometric contrast<br>{number(artifact['dots'])} dots · {artifact['bytes']/1024:.0f} KB · one GeoTIFF</p><a class="button primary" href="{download}" download>Download new research TIF <span>↓</span></a><p class="download-warning">Download: YES &nbsp; / &nbsp; Competition submission: NO</p><p class="muted">Local checks passed; portal acceptance untested.</p><a class="quiet-link" href="submission-guide.html">What must pass before a submission? →</a></div></section>
<section class="metric-grid" aria-label="Key results"><article class="metric-card"><span>HOLDOUT-DTI</span><strong>{holdout['dti']:.4f}</strong><small>95% CI {holdout['ci95']['interval'][0]:.4f}–{holdout['ci95']['interval'][1]:.4f}</small></article><article class="metric-card"><span>Matched-budget ablation</span><strong>{base['dti']:.4f}</strong><small>HOLDOUT-DTI · 95% CI {base['ci95']['interval'][0]:.4f}–{base['ci95']['interval'][1]:.4f}</small></article><article class="metric-card"><span>Final-dot uniqueness</span><strong class="negative">Failed</strong><small>{pct(non_lattice[0]['candidate_dot_overlap_within_3px'])} vs a LiDAR comparator; {pct(ordered[0]['candidate_dot_overlap_within_3px'])} vs lattice</small></article><article class="metric-card"><span>Competition slots used</span><strong>0</strong><small>Entity cap: 3/week in rules; remaining unknown</small></article></section>
<section class="section"><div class="section-heading"><h2>The new downloadable artifact</h2><span class="pill fail">RESEARCH ONLY</span></div><div class="table-wrap"><table><thead><tr><th>Downloadable filename</th><th>Measured local performance</th><th>Unique versus prior artifacts?</th><th>Submission eligibility</th></tr></thead><tbody><tr><td><a href="{download}" class="filename" download>{esc(filename)}</a></td><td><strong>HOLDOUT-DTI {holdout['dti']:.4f}</strong><small class="table-hint">95% CI {holdout['ci95']['interval'][0]:.4f}–{holdout['ci95']['interval'][1]:.4f}</small><small class="table-hint">Leaderboard: not estimable</small></td><td>Distinct bytes & prediction: yes.<small class="table-hint">Protocol uniqueness: NO (final-dot overlap).</small></td><td><strong>DO NOT SUBMIT</strong><small class="table-hint">Negative result; no selector approval.</small></td></tr></tbody></table></div></section>
<div class="metric-footnote"><strong>HOLDOUT-DTI metadata:</strong> evaluator <code>{holdout['evaluator_version']}</code> · {number(holdout['n_withheld_positive_pixels'])} withheld positive pixels · four spatial folds · whole-component hiding with 1.5 km collar · pooled TP/FP/FN · 10 km block bootstrap, {number(holdout['ci95']['resamples'])} resamples. These are not leaderboard estimates.</div>
<section class="section"><div class="section-heading"><div><span class="eyebrow">THE NINE-SITE REVIEW</span><h2>Which file should I submit?</h2></div><a class="quiet-link" href="sites.html">Individual executive summaries →</a></div><p><strong>None is currently approved under your protocol.</strong> GEMSDOE32 has the highest historical <em>user-reported</em> value among these nine. The existing leaders are related or overlapping predictions, not nine independent discoveries. Each row below links to its own audit page.</p><div class="table-wrap"><table class="portfolio-table"><thead><tr><th>Project</th><th>Organizer receipt</th><th>File inspected — not a new recommendation</th><th>Protocol unique?</th><th>Estimated leaderboard score</th><th>New file to submit</th></tr></thead><tbody>{rows}</tbody></table></div></section>
<section class="two-column section"><article class="panel"><span class="eyebrow">WHY DID GEMSDOE32 LEAD THE FAMILY?</span><h2>Less redundant mass, not a new detector.</h2><div class="flow"><div><strong>44,090</strong><span>D2.8 dots</span></div><span>→</span><div><strong>37,654</strong><span>after 200 m pruning</span></div></div><p>Byte-level analysis confirms that H33-B2 is exactly D2.8 with {number(focus['relationships']['gems32_removed_d28_pixels'])} near-catalogue dots removed. It adds <strong>zero</strong> new locations. If removal preserves weighted true-positive coverage while reducing false-positive mass, DTI rises. That is a plausible mechanism, not proof of what caused an unauthenticated historical result.</p><p>Known faults are masked <em>pixel-exactly</em>; nearby new faults can still matter. A 200 m deletion is therefore not universally safe.</p><a class="quiet-link" href="sites/GEMSDOE32.html">Read the exact forensic result →</a></article><article class="panel"><span class="eyebrow">HONEST ESTIMATION</span><h2>A holdout is not a leaderboard forecast.</h2><p>There is no defensible numerical leaderboard estimate for the new file. Existing-fault recovery differs from detecting the organizer’s undisclosed new faults. Regressing a handful of related, unreceipted historical values would create false precision.</p><p>The public top row at our dated inspection differed from both inherited claims. That observation is preserved in the source ledger, not attributed to a local file or treated as an exact-file receipt.</p><a class="quiet-link" href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">Review the organizer’s live board ↗</a></article></section>
<section class="two-column section"><article class="panel"><span class="eyebrow">AUTOMATED DECISION</span><h2>Every gate is visible.</h2><table class="gate-table"><thead><tr><th>Validation gate</th><th>Result</th></tr></thead><tbody>{gate_rows}</tbody></table><p class="muted">A format pass cannot override a scientific or uniqueness failure. Nothing here uploads or selects a competition slot.</p></article><article class="panel"><span class="eyebrow">THE EXACT ARTIFACT</span><h2>Traceable to the byte.</h2><label class="field-label" for="submission-name">Unique name</label><textarea id="submission-name" rows="3" readonly>{esc(experiment['submission_name'])}</textarea><label class="field-label" for="submission-note">Short note · {len(note)} / 140 characters</label><textarea id="submission-note" rows="3" readonly>{esc(note)}</textarea><button class="button secondary" type="button" data-copy="submission-note">Copy research note</button><span class="copy-status" role="status" aria-live="polite"></span><label class="field-label">Raster SHA-256</label><code class="hash">{artifact['sha256']}</code><p class="muted">EPSG:32611 · 3,730 × 3,292 · float32 · raw values [0,1], all finite. An internal footprint mask makes the exterior null on masked reads. No portal receipt exists.</p><a class="quiet-link" href="data/run-card.json">Full validator & run card ↗</a></article></section>
<section class="panel irregularities"><span class="eyebrow">FLAGGED, NOT HIDDEN</span><h2>Important irregularities.</h2><ul><li>The prompt does not include the required single-method lane assignment.</li><li>Two historic TIFFs are incompatible with the comparison contract; other named repositories are not exhaustively audited.</li><li>Current GEMSDOE28 and GEMSDOE33 files do not match older peer descriptions of their counts or ancestry.</li><li>The mirrored sample contains positive fault labels; only its grid and finite mask are used.</li><li>Source mirrors are hash-pinned but not organizer-authenticated. Account receipts and remaining weekly quota require an authenticated competition session, unavailable here.</li></ul><a class="quiet-link" href="sources.html">Evidence, source status & next steps →</a></section>'''
    if (ROOT / "evidence/source-health.json").exists():
        health = load("evidence/source-health.json")
        changed = [row["repo"].split("/")[-1] for row in health["snapshots"] if row["status"] == "snapshot_drift"]
        if changed:
            overview += f'<section class="notice section"><strong>Snapshot drift flagged:</strong> {esc(", ".join(changed))} advanced after the frozen registry inventory. No evidence was silently refreshed and no global uniqueness is claimed. <a href="sources.html#automation">Automated source diagnostic →</a></section>'
    (DOCS / "executive-summary.html").write_text(shell("Executive summary", overview))
    (DOCS / "index.html").write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url=executive-summary.html"><title>ApartGEMS — Submission readiness</title></head><body><p><a href="executive-summary.html">Open the executive summary and research TIF download</a>. Current verdict: <strong>DO NOT SUBMIT</strong>.</p></body></html>''')
    (ROOT / "index.html").write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url=docs/executive-summary.html"><title>ApartGEMS</title></head><body><a href="docs/executive-summary.html">Executive summary, nine-site audits and research TIF download</a> — DO NOT SUBMIT this negative candidate.</body></html>''')
    (ROOT / ".nojekyll").touch()
    (DOCS / ".nojekyll").touch()
    site_body = f'''<div class="page-heading"><div><span class="eyebrow">PORTFOLIO / HISTORICAL EVIDENCE</span><h1>Nine sites. One clear decision.</h1><p class="lead">Separate byte-level reviews, without pretending related files are independent wins.</p></div></div><div class="notice"><strong>No new submission is approved.</strong> All historical values are unverified user reports. File identity is measured; score identity is not. The only new artifact is the AP1-SNRC research file on the executive summary, not nine renamed copies.</div><div class="site-grid">{''.join(site_card(row) for row in focus['rows'])}</div><section class="panel section"><h2>Audit scope</h2><p>{registry['inventory_count']} paths, {registry['unique_byte_blobs']} distinct byte blobs, {registry['unique_prediction_rasters']} distinct compatible prediction arrays. There were {registry['failed_fetches']} failed downloads and {registry['incompatible_rasters']} incompatible files. Exterior NaN/zero encodings and compression differences do not count as new predictions.</p><a class="quiet-link" href="data/focus-audit.json">Download full pairwise forensic evidence ↗</a></section>'''
    (DOCS / "sites.html").write_text(shell("Nine-site review", site_body, "Nine-site review"))
    for row in focus["rows"]:
        aliases = ", ".join(row["exact_prediction_alias_sites"]) or "No exact cross-site alias found in this snapshot"
        peers = [x for x in focus["pairs"] if x["candidate_site"] == row["site"]]
        most_similar = max(peers, key=lambda x: x["candidate_within_3px_of_reference"])
        content = f'''<div class="page-heading"><div><span class="eyebrow">SITE EXECUTIVE SUMMARY</span><h1>{row['site']}</h1><p class="lead">Historical best claim, exact artifact check, and what to download today.</p></div></div><section class="decision-grid"><article class="decision-panel"><span class="pill fail">NO APPROVED SUBMISSION</span><h2>Do not resubmit<br>the historical file.</h2><p>It is not a protocol-unique new prediction. Its greatest directional 3 px overlap with another focus-site leader is <strong>{pct(most_similar['candidate_within_3px_of_reference'])}</strong> ({most_similar['reference_site']}). Renaming or changing exterior encoding does not make it new.</p><a class="quiet-link" href="../executive-summary.html">Current new-file decision →</a></article><article class="download-panel"><span class="eyebrow">NEW FILE FOR THIS SITE</span><h2>None approved.</h2><p>Estimated leaderboard score: <strong>not estimable</strong>. There is no organizer-confirmed receipt or validated leaderboard calibration for a new file.</p><a class="button primary" href="../{download}" download>Download AP1-SNRC research TIF ↓</a><p class="download-warning">Research download only. DO NOT SUBMIT.</p></article></section><section class="panel section"><span class="eyebrow">HIGHEST HISTORICAL USER REPORT IN THE BRIEF</span><h2>Historical claim only <span class="inline-muted">— no organizer receipt</span></h2><p><code>{esc(row['historical_claimed_best_name'])}</code></p><p>This is neither HOLDOUT-DTI nor ORGANIZER-CONFIRMED. No exact-file submission-page receipt was supplied. It must not be used as a measured score for an automatically selected file.</p><dl class="facts"><dt>Exact file inspected</dt><dd><code>{esc(row['inspected_filename'])}</code></dd><dt>Positive pixels</dt><dd>{number(row['positive_pixels'])}</dd><dt>Exactly on known faults</dt><dd>{number(row['on_catalogue'])}</dd><dt>Within 200 m of catalogue</dt><dd>{number(row['within_200m_of_catalogue'])}</dd><dt>Exact prediction aliases in other sites</dt><dd>{esc(aliases)}</dd><dt>Raster SHA-256</dt><dd><code>{row['sha256']}</code></dd><dt>Pinned source commit</dt><dd><code>{row['source_commit']}</code></dd></dl><a class="quiet-link" href="{esc(row['source_url'])}">Inspect the pinned historical file on GitHub ↗</a></section>'''
        if row["site"] == "GEMSDOE32":
            content += '''<section class="panel section"><h2>Why the B2 pruning could help</h2><p>Measured identity: H33-B2 is exactly D2.8 after removing 6,436 dots at distance ≤200 m from known faults. There are zero newly added locations. The organizer masks only known-fault pixels themselves, not this surrounding band.</p><p>For fixed truth, DTI = TPw / (TPw + 0.2 FPw + 0.8 FNw). If pruning leaves TPw unchanged, FNw also stays fixed and reducing FPw increases DTI. But if real new faults lie near known traces, pruning can remove useful coverage. The official staff explicitly confirms that such new-fault pixels can occur.</p><p>Thus emission geometry and catalogue-flank false-positive removal are a plausible explanation of the family’s reported improvement. The exact hidden-test cause and the historical score-to-file pairing remain unverified. It does not establish that a new model will beat it.</p><a class="quiet-link" href="https://community.drivendata.org/t/scoring-clarification-are-known-usgs-ingenious-faults-masked-when-scoring-and-are-they-in-the-final-round-label-set/11516/4">Official masking clarification ↗</a></section>'''
        if row["site"] in ("GEMSDOE28", "GEMSDOE33"):
            content += f'''<section class="panel irregularities section"><h2>Source discrepancy</h2><p>The current restored file contains {number(row['positive_pixels'])} positive pixels. Older peer summaries describe a different count/ancestry. The measured byte identity takes precedence for this audit, but it cannot prove which bytes were actually submitted for the historical report. See the raw relationship tests, not a reconstructed story.</p><a class="quiet-link" href="../data/focus-audit.json">Exact additions/removals and source pins ↗</a></section>'''
        content += f'''<section class="panel section"><h2>Today’s measured new experiment</h2><p><strong>AP1-SNRC HOLDOUT-DTI: {holdout_text(holdout)}</strong>; evaluator <code>{holdout['evaluator_version']}</code>, {number(holdout['n_withheld_positive_pixels'])} withheld positives. It did not beat the matched-budget ablation and fails final-dot uniqueness. The current verdict is <strong>negative</strong>, not a forecast for this site.</p><p>This page lives in ApartGEMSDOE1. The independent external {row['site']} website was audited, not edited.</p></section>'''
        (DOCS / "sites" / f"{row['site']}.html").write_text(shell(row["site"], content, "Nine-site review", prefix="../"))
    guide = f'''<div class="page-heading"><div><span class="eyebrow">COMPETITION / SUBMISSION GUIDE</span><h1>From prediction to submission.</h1><p class="lead">Automated inspection first. A competition slot is a separate decision.</p></div></div><div class="notice danger"><strong>Current stop:</strong> AP1-SNRC is a negative result. Downloading the research file is safe; submitting it is not approved. Do not follow the upload steps below for this file.</div><section class="panel section"><h2>The GeoTIFF contract</h2><ul><li>One band, float32, values in [0,1], no NaN inside the footprint.</li><li>CRS EPSG:32611; dimensions 3,730 × 3,292; 100 m pixels; transform [100, 0, 243350, 0, -100, 4508550]. These dimensions are measured from the pinned template, not guessed from the CRS.</li><li>The official text requires null or NaN outside the footprint. This file uses zero numeric values plus an internal validity mask: raw range checks pass and masked reads return exterior nulls. This encoding has not been accepted by the organizer portal in this session.</li><li>A ZIP, if used, must contain exactly one TIFF. The main download here is already a single .tif; no archive handling is needed.</li></ul><p>The reported “Predicted values must be in range [0, 1]” error cannot be diagnosed without the rejected bytes and portal receipt. We prevent out-of-range values, infinities and raw NaNs locally rather than asserting a speculative cause.</p><a class="quiet-link" href="https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/#submission-format">Official submission format ↗</a></section><section class="panel section"><h2>Reproduce the automated pipeline</h2><pre tabindex="0" role="region" aria-label="Release verification commands"><code>python -m venv .venv
.venv/bin/pip install -r requirements.txt
.venv/bin/python scripts/build_site.py
.venv/bin/python scripts/verify_release.py
.venv/bin/pytest -q</code></pre><p>The shipped release can be checked without bulk raw data. For input inspection only:</p><pre tabindex="0" role="region" aria-label="Data restoration commands"><code>.venv/bin/python scripts/restore_data.py
.venv/bin/python scripts/prepare_data.py
.venv/bin/python scripts/source_health.py --github-only</code></pre><p>The recorded experiment is frozen. The runner refuses an implicit rerun if its evidence file exists. Verify the shipped result instead; do not delete it to evade the duplicate stop or experiment cap. Future lanes need a new preregistered run identity and budget ledger, not a renamed copy.</p></section><section class="panel section"><h2>Only after a future file is approved</h2><ol class="steps"><li><strong>Check the executive decision.</strong> It must show every gate passed and a separate selector decision, including an account-verified remaining slot. No “inspection-only” file is upload-authorized.</li><li><strong>Download the exact approved .tif.</strong> Compare its SHA-256 against the release receipt; do not alter values, name metadata, CRS or compression after the check.</li><li><strong>Open the authenticated submission form.</strong> Choose the approved TIFF as “File to submit” and paste its short note. An authenticated account is required; this project does not request or store credentials.</li><li><strong>Respect the entity-wide cap.</strong> The rules state up to three scoring submissions per week per participating entity. Parallel sites do not create extra slots. The submission page is authoritative for the current allowance.</li><li><strong>Record the receipt.</strong> Link the exact file SHA-256 to the submission-page id, time and returned value. Only this evidence may be labeled ORGANIZER-CONFIRMED.</li><li><strong>Final selection is separate.</strong> Select one final submission for both prize rounds before the organizer deadline. This research run has selected none.</li></ol><a class="quiet-link" href="https://www.drivendata.org/competitions/306/competition-doe-gems/submissions/">Organizer submissions page (login required) ↗</a></section>'''
    (DOCS / "submission-guide.html").write_text(shell("Submission guide", guide, "Submission guide"))
    research = f'''<div class="page-heading"><div><span class="eyebrow">SCIENCE / PREREGISTRATION</span><h1>A physical hypothesis, not a renamed raster.</h1><p class="lead">Fault mapping supports geothermal exploration. It does not itself establish a vent or a viable reservoir.</p></div></div><section class="panel"><h2>AP1-SNRC: the tested mechanism</h2><p>Paired local potassium-versus-thorium rank residuals are sampled across the LiDAR strike normal, with a scarp step, signed-curvature amplitudes and a soft RTP-gradient corroborator. Quantized byte values are descriptors, not physical concentrations. No registry prediction or known-fault proximity is a field input.</p><p><strong>Named mimics:</strong> alluvial material contacts, fluvial terraces, paleolake shorelines and mine cuts. Source coverage and survey boundaries can also create apparent edges; unavailable neighborhoods are excluded without labels.</p><h3>Measured outcome</h3><p>Candidate <strong>HOLDOUT-DTI {holdout_text(holdout)}</strong>; ablation <strong>HOLDOUT-DTI {holdout_text(base)}</strong>. Both use <code>{holdout['evaluator_version']}</code> and {number(holdout['n_withheld_positive_pixels'])} withheld positives. Paired delta {paired['paired_delta_dti']:+.5f}, 95% CI [{paired['paired_delta_ci95'][0]:+.5f}, {paired['paired_delta_ci95'][1]:+.5f}]; {paired['fold_wins']} of {paired['n_folds']} fold wins. There is no evidence of improvement.</p><p>All {experiment['canary']['n_features_checked']} individual source/descriptor canaries passed the 0.90 two-polarity AUC threshold. Passing a canary does not prove independence, fault discovery, or high performance.</p></section><section class="panel section"><h2>Ranked before implementation</h2><div class="table-wrap"><table><thead><tr><th>Rank / hypothesis</th><th>Layers & signature</th><th>Expected value / cost</th><th>Status</th></tr></thead><tbody><tr><td>1 · Scarp-normal radiometric contrast</td><td>LiDAR step, curvature and strike; local K/Th rank residual contrast; RTP gradient</td><td>Moderate plausibility, uncertain / low–medium</td><td>Tested negative. Lane stopped.</td></tr><tr><td>2 · Opposite-curvature scarplet pairs</td><td>LiDAR positive/negative curvature pairing and coherent step</td><td>Moderate plausibility / low</td><td>Proposal only; not another experiment in this lane.</td></tr><tr><td>3 · Paired gravity/magnetic edge-offset dispersion</td><td>RTP and isostatic gravity derivative-edge positions across scales</td><td>Low–moderate plausibility / medium</td><td>Proposal only; unvalidated.</td></tr><tr><td>4 · Drainage-capture elbow chains</td><td>Unmodified USGS 3DEP DEM, connected flow geometry and profile veto</td><td>Unknown / high</td><td>Not viable here until specific raw tiles are obtainable and verified.</td></tr></tbody></table></div><p>These are unimplemented in the initially empty local repository, not claimed to be globally novel. Related radiometric, LiDAR, gravity and drainage ideas already appear in peer projects. Expected value is qualitative judgment, not a numerical score estimate.</p><a class="quiet-link" href="research/hypotheses-2026-10-27.md">Full preregistration, differences, mimics & data requirements ↓</a></section><section class="panel section"><h2>Validation without hidden-label leakage</h2><p>The shared template is copied byte-for-byte with source pins and checksum tests. Whole 8-connected fault components touching each quadrant/collar are hidden everywhere; features consume no fault catalogue. Training masks exclude the withheld regions and whole components with a buffer. Visible faults are masked pixel-exactly during evaluation. Connected components are a conservative raster proxy, not actual fault-segment IDs.</p><p>TPw, FPw and FNw are pooled, not fold-average ratios. The conditional 95% CI resamples 10 km spatial blocks. It quantifies internal validation uncertainty, not hidden-leaderboard uncertainty. A registry check occurs before placement and again on all final dots. No lattice-control exemption or registry-conditioned placement is used.</p><a class="quiet-link" href="data/experiment.json">Read the complete experiment evidence ↗</a></section>'''
    (DOCS / "research.html").write_text(shell("Science & method", research, "Science & method"))
    source_rows = "".join(f'<tr><td><strong>{esc(row["id"])}</strong><small class="table-hint">{esc(row["publisher"])}</small></td><td>{esc(row["status"])}</td><td>{esc(" ".join(row["claims_supported"]))}</td><td><a href="{esc(row["url"])}">Official source ↗</a></td></tr>' for row in sources["sources"])
    source_body = f'''<div class="page-heading"><div><span class="eyebrow">EVIDENCE / SOURCE REGISTER</span><h1>Know what is verified.</h1><p class="lead">A source link is not a measurement. A snapshot is not a live feed.</p></div></div><section class="panel"><h2>Evidence classes</h2><div class="evidence-grid"><div><span class="pill pass">HOLDOUT-DTI</span><p>Local evaluated result with version, withheld positives and 95% CI.</p></div><div><span class="pill neutral">ORGANIZER-CONFIRMED</span><p>Reserved for exact-file submission-page receipts. None was available for these historical claims.</p></div><div><span class="pill warning">USER REPORT / HYPOTHESIS</span><p>Explicitly unverified; never presented as a measurement or calibrated forecast.</p></div></div><p>The public leaderboard’s displayed top row is an official-page observation, a fourth source class—not a receipt for any downloaded file.</p></section><section class="section"><div class="section-heading"><h2>Official and research sources</h2><a class="quiet-link" href="data/sources.json">Download source ledger ↓</a></div><div class="table-wrap"><table><thead><tr><th>Source</th><th>Observed status</th><th>What it supports</th><th>Review</th></tr></thead><tbody>{source_rows}</tbody></table></div></section><section class="panel section"><h2>Limits that block a successful submission</h2><ul><li><strong>Scientific:</strong> this candidate did not improve holdout performance. No result demonstrates a leaderboard gain.</li><li><strong>Uniqueness:</strong> final dots exceed the strict overlap limit against five registry predictions, including a genuine LiDAR comparator even without the space-filling lattice.</li><li><strong>Access:</strong> public pages are readable through the page-retrieval tool; sandbox processes can access only GitHub and package registries. Bulk external acquisitions and authenticated receipts are not available through this environment.</li><li><strong>Provenance:</strong> data caches are byte-pinned owner mirrors; the sample’s values contradict the total-absence description. Upstream peer code has no clear license file in the inspected template snapshot; redistribution/prize-use rights for that code are not established by a hash.</li><li><strong>Comparability:</strong> peers use different split/evaluator versions and several summaries disagree with current bytes. A common portable current-best OOF prediction benchmark is still needed.</li><li><strong>Scope:</strong> these are executive subpages for all nine sites in this repository. Their independent GitHub Pages websites were not modified.</li></ul></section><section class="panel section"><h2>Next session, in priority order</h2><ol><li>Assign a single explicit new research lane. Do not rerun or tune the stopped SNRC lane.</li><li>Reconcile organizer receipts to exact historical TIFF hashes and establish a common current-best holdout benchmark.</li><li>Resolve code-use rights and independently authenticate raw/template data provenance.</li><li>Investigate a genuinely different observable—such as concealed subsurface boundary geometry—rather than another correlated scarp thinning or copied champion.</li><li>Verify specific official raw-data endpoints before adopting any external-data-dependent hypothesis; the generic 3DEP URL tested here returned 404.</li><li>Keep the entity-wide slot ledger current in an authenticated environment. No repository or parallel run should spend a slot without the separate selector.</li></ol></section><section class="panel section"><h2>Freshness, not false real-time claims</h2><p>The shipped results are an immutable 27 October snapshot. The scheduled source-health workflow checks public URLs and peer HEADs, records failures, and opens an update PR; it never silently re-scores, changes a research verdict or auto-submits. The browser does not poll login-walled pages or invent current scores. Review the current source-health JSON if available.</p><a class="quiet-link" href="https://github.com/apartanish22-droid/ApartGEMSDOE1/actions">View scheduled audit runs ↗</a></section>'''
    report_rows = []
    for title, name, key in [("Research-release inspection", "release-verification.json", "research_release_valid"),
                              ("Desktop/mobile/browser checks", "browser-verification.json", "passed"),
                              ("Fresh pinned-data restoration", "restoration-verification.json", "passed"),
                              ("Three-pass requirements review", "review-ledger.json", "review_complete")]:
        path = ROOT / "evidence" / name
        if path.exists():
            value = load("evidence/" + name)
            status = "PASS (research only)" if value.get(key) is True else "NOT PASSED"
            report_rows.append(f'<li><a href="data/{name}" download>{esc(title)} ↓</a> — {status}</li>')
        else:
            report_rows.append(f'<li>{esc(title)} — report not yet recorded</li>')
    source_body += f'<section id="automation" class="panel section"><h2>Automated checks, inspectable evidence</h2><ul>{"".join(report_rows)}<li><a href="data/source-health.json" download>Source reachability &amp; snapshot drift ↓</a> — mode and UTC timestamp are in the report; unknown/prohibited probes are never marked verified.</li></ul><p>Weekly GitHub Actions checks permitted official sources and GitHub heads, without rewriting the frozen registry or automatically monitoring DrivenData/leaderboard values. A successful check is not a competition upload approval.</p><p><a href="data/claims.csv" download>Claim-by-claim evidence table ↓</a> · <a href="data/data-catalog.csv" download>Official/free-data availability catalogue ↓</a></p></section>'
    (DOCS / "sources.html").write_text(shell("Sources & limits", source_body, "Sources & limits"))
    # Human-readable, downloadable main deliverable independent of JavaScript.
    lines = ["# ApartGEMSDOE1 — executive summary", "", "**DO NOT SUBMIT the new candidate.** It is a technically valid, independently generated research TIFF, not a protocol-unique or high-performing approved submission.", "",
             f"- [Download the new research TIFF]({download}) (research only; {artifact['bytes']:,} bytes).",
             f"- SHA-256: `{artifact['sha256']}`.",
             f"- Name: `{experiment['submission_name']}`.", f"- Note ({len(note)}/140 characters): `{note}`.",
             f"- HOLDOUT-DTI: **{holdout_text(holdout)}**, evaluator `{holdout['evaluator_version']}`, {holdout['n_withheld_positive_pixels']:,} withheld positive pixels.",
             f"- Matched-budget ablation HOLDOUT-DTI: **{holdout_text(base)}**, same evaluator/positives.",
             f"- Paired HOLDOUT-DTI delta: {paired['paired_delta_dti']:+.6f}; 95% CI [{paired['paired_delta_ci95'][0]:+.6f}, {paired['paired_delta_ci95'][1]:+.6f}]; {paired['fold_wins']}/4 fold wins.",
             f"- Byte-unique and prediction-distinct vs {registry['unique_prediction_rasters']} compatible registry arrays: **yes**. Protocol-unique: **no**.",
             f"- Final-dot overlap: **{pct(ordered[0]['candidate_dot_overlap_within_3px'])}** vs lattice, **{pct(non_lattice[0]['candidate_dot_overlap_within_3px'])}** vs a non-lattice LiDAR submission. The strict threshold is 70%; no exemption was applied.",
             "- Leaderboard estimate: **not estimable**. No organizer-confirmed result for this file.",
             "- One experiment completed; stopped on duplicate final dots. No further arms, slot selections or competition uploads.", "", "## Nine-site decisions", "", "All historical values below are **unverified user reports, not organizer receipts or local HOLDOUT-DTI**. Every historical file is reference-only, not a new-file recommendation.", "",
             "| Site | Historical best claim | File inspected | Protocol-unique vs other leaders? | Estimated leaderboard score | New approved file |", "|---|---|---|---|---|---|"]
    for row in focus["rows"]:
        lines.append(f"| [{row['site']}](sites/{row['site']}.html) | No exact-file receipt | `{row['inspected_filename']}` | No | Not estimable | None |")
    lines += ["", "## Why GEMSDOE32 led the reported family", "", "The restored H33-B2 prediction is exactly the 44,090-dot D2.8 mask after removing 6,436 dots within 200 m of the public catalogue. It contains 37,654 dots and zero new locations. Removing false-positive mass can increase DTI if weighted TP coverage is preserved. This is a plausible metric mechanism, not proof of the hidden cause or an authenticated exact-file receipt. New faults can exist within 300 m of known traces, so flank pruning is not universally safe.", "", "The public leaderboard was inspected on 2026-10-27 and did not match the two inherited top-value claims. Its observation is recorded in the source ledger, not presented as an exact-file organizer receipt. No leaderboard number is used to estimate this file’s performance.", "", "## Exact forensic findings", "", "- GEMSDOE25 and GEMSDOE30: identical in-footprint predictions despite different TIFF bytes.", "- GEMSDOE28 H27 and GEMSDOE31 H27: identical in-footprint predictions.", "- GEMSDOE36 contains all 37,654 H33-B2 pixels plus 1,200 others.", "- Current GEMSDOE28 rung file has 37,660 positives and current GEMSDOE33 analog file has 41,865; their older peer ancestry/count descriptions do not match the restored bytes.", "- All nine historical leaders violate the near-dot overlap threshold against at least one other focus leader.", "", "## Format and access", "", "The new file is a single float32 GeoTIFF, EPSG:32611, shape 3730×3292, exact template transform, with no NaN/Inf and all raw values in [0,1]. An internal validity mask marks only the exterior as null on masked reads. This interpretation of the organizer’s null/NaN rule has not been portal-tested; the cause of the previously reported upload error is unknown without the rejected bytes/receipt.", "", "Public source pages were read, but account receipts and remaining weekly quota redirect to login. Raw inputs are checksum-pinned owner mirrors, not independently organizer-authenticated. Two incompatible peer TIFFs and the other listed repositories prevent a global uniqueness certification. The method paragraph/lane assignment is absent. The separate selector was not invoked. These are automated evidence outcomes, not a request for human inspection.", "", "## Next steps", "", "1. Start a different, explicitly assigned lane; do not tune the stopped lane.", "2. Bind historical organizer receipts to exact file hashes and establish a common current-best holdout benchmark.", "3. Authenticate raw-data provenance and resolve shared-code redistribution/prize-use rights.", "4. Investigate independent concealed-structure observables and verify concrete official data downloads before adoption.", "5. Maintain the entity-wide authenticated slot ledger (rules: up to three per week).", "", "## Evidence and official sources", "", "- [Complete run card](data/run-card.json)", "- [Experiment, evaluator version and CI details](data/experiment.json)", "- [Pairwise nine-site audit](data/focus-audit.json)", "- [Preregistered hypothesis slate](research/hypotheses-2026-10-27.md)", "- [Official sources and their evidence limits](sources.html)", "- [Competition problem/metric/format](https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/)", "- [Staff pixel-exact masking clarification](https://community.drivendata.org/t/scoring-clarification-are-known-usgs-ingenious-faults-masked-when-scoring-and-are-they-in-the-final-round-label-set/11516/4)", "- [Official rules, section 3](https://docs.nlr.gov/docs/fy26osti/96647.pdf)", "", "This repository hosts nine site-specific executive subpages. It does not claim to have edited the nine independent external websites.", ""]
    (DOCS / "executive-summary.md").write_text("\n".join(lines))
    (DOCS / "data/summary.json").write_text(json.dumps({"status": "DO NOT SUBMIT", "ok_to_submit": False,
        "artifact": artifact, "holdout": holdout, "leaderboard_estimate": None,
        "historical_reports_authenticated": False, "generated_utc": experiment["finished_utc"]}, indent=2) + "\n")
    stream = io.StringIO()
    writer = csv.writer(stream)
    writer.writerow(["site", "organizer_receipt_status", "inspected_file", "sha256", "positive_pixels", "protocol_unique", "leaderboard_estimate", "new_approved_file", "source_url"])
    for row in focus["rows"]:
        writer.writerow([row["site"], "NONE", row["inspected_filename"], row["sha256"], row["positive_pixels"], False, "NOT_ESTIMABLE", "NONE", row["source_url"]])
    (DOCS / "data/nine-site-summary.csv").write_text(stream.getvalue())
    print(f"Built executive summary, nine site subpages, submission guide, research, sources, CSV and JSON. Artifact: {filename}")


